export const MASCOT_CSS = ".mascot{overflow:visible}.mascot .m-body,.mascot .m-eyes,.mascot .m-lines path,.mascot .m-lines g,.mascot .m-prop,.mascot .m-shadow{transform-box:view-box}.mascot.m-enter{animation:m-enter var(--ml-dur-enter) var(--ml-ease-enter) both}.mascot .m-eyes{transform-origin:62px 71px;animation:m-blink calc(var(--ml-dur-shared) * 10) var(--ml-ease-inout) calc(var(--ml-dur-shared) * 4) 3}.mascot-wave .m-line-wave{transform-origin:111.5px 56px;animation:m-wave calc(var(--ml-dur-slow) * 2) var(--ml-ease-inout) var(--ml-dur-enter) 3}.mascot-empty .m-line-ghost{animation:m-ghost calc(var(--ml-dur-shared) * 3) var(--ml-ease-inout) var(--ml-dur-enter) 3}.mascot-error .m-line-tangle{transform-origin:111.5px 74px;animation:m-wobble calc(var(--ml-dur-slow) * 2) var(--ml-ease-inout) 3}.mascot-celebrate .m-body{animation:m-jump calc(var(--ml-dur-slow) * 2) var(--ml-ease-inout) 3}.mascot-celebrate .m-shadow{transform-origin:80px 140px;animation:m-shadow calc(var(--ml-dur-slow) * 2) var(--ml-ease-inout) 3}.mascot-celebrate .m-prop-sparkles{animation:m-twinkle calc(var(--ml-dur-shared) * 2) var(--ml-ease-inout) 3}.mascot-search .m-line-lens{transform-origin:111.5px 56px;animation:m-sweep calc(var(--ml-dur-shared) * 3) var(--ml-ease-inout) var(--ml-dur-enter) 2}@keyframes m-enter{from{opacity:0;transform:translateY(8px) scale(.96)}to{opacity:1;transform:none}}@keyframes m-blink{0%,92%,100%{transform:scaleY(1)}95%{transform:scaleY(.1)}}@keyframes m-wave{0%,100%{transform:rotate(0)}25%{transform:rotate(-16deg)}75%{transform:rotate(8deg)}}@keyframes m-ghost{0%,100%{opacity:1}50%{opacity:.35}}@keyframes m-wobble{0%,100%{transform:rotate(0)}30%{transform:rotate(8deg)}70%{transform:rotate(-6deg)}}@keyframes m-jump{0%,100%{transform:translateY(0)}45%{transform:translateY(-8px)}}@keyframes m-shadow{0%,100%{transform:scaleX(1);opacity:.1}45%{transform:scaleX(.7);opacity:.05}}@keyframes m-twinkle{0%,100%{opacity:1;transform:scale(1)}50%{opacity:.5;transform:scale(.9)}}@keyframes m-sweep{0%,100%{transform:rotate(0)}30%{transform:rotate(-12deg)}70%{transform:rotate(6deg)}}@media (prefers-reduced-motion: reduce){.mascot,.mascot *{animation:none!important}}";
